/**
 * ReleaseNotifier — Posts version info and release notes to Slack on startup.
 * Reads dist/version.json (generated by CI) and posts to DEFAULT_UPDATE_CHANNEL.
 *
 * The notice says what changed on THIS host (release-notes.ts): from the version this deploy replaced here
 * (dist/previous-version.json) to the shipped one, out of dist/release-history.json. It is posted once per deploy: a
 * restart of the same build finds it in DATA_DIR/release-notified.json and posts nothing.
 */

import type { WebClient } from '@slack/web-api';
import { atomicWriteJson, readJsonWithBackup } from '@soma/common/atomic-json';
import { DATA_DIR, ENV_FILE } from '@soma/common/env-paths';
import { Logger } from '@soma/common/logger';
import { existsSync, readFileSync } from 'fs';
import path from 'path';
import { hostReleaseNotes, type ReleaseHistory } from './release-notes';

const logger = new Logger('ReleaseNotifier');

export interface VersionInfo {
  version: string;
  previousVersion: string;
  tag: string;
  previousTag: string;
  commitHash: string;
  commitHashShort: string;
  commitTime: string;
  branch: string;
  releaseTrack?: string;
  buildTime: string;
  releaseNotes: string;
  isRollback?: boolean;
  rollbackTargetTag?: string | null;
  rollbackTargetVersion?: string | null;
}

/** Where the notifier reads the shipped files and keeps its once-per-deploy record (tests point both elsewhere). */
export interface ReleaseNotifierPaths {
  readonly distDir: string;
  readonly notifiedFile: string;
}

const defaultPaths = (): ReleaseNotifierPaths => ({
  distDir: path.join(process.cwd(), 'dist'),
  notifiedFile: path.join(DATA_DIR, 'release-notified.json'),
});

/** The build this host last announced. */
interface NotifiedRecord {
  readonly tag: string;
  readonly commitHash: string;
  readonly buildTime: string;
}

function parseNotified(raw: unknown): NotifiedRecord {
  const r = raw as Partial<NotifiedRecord> | null;
  if (!r || typeof r.tag !== 'string' || typeof r.commitHash !== 'string' || typeof r.buildTime !== 'string') {
    throw new Error('not a release-notified record');
  }
  return { tag: r.tag, commitHash: r.commitHash, buildTime: r.buildTime };
}

/** An optional shipped JSON file: absent or unreadable is `null` (logged), never a failed startup. */
function readOptionalJson<T>(file: string, what: string): T | null {
  if (!existsSync(file)) return null;
  try {
    return JSON.parse(readFileSync(file, 'utf-8')) as T;
  } catch (error) {
    logger.warn(`Failed to read ${what}`, { file, error: (error as Error).message });
    return null;
  }
}

function loadVersionInfo(distDir = path.join(process.cwd(), 'dist')): VersionInfo | null {
  const versionPath = path.join(distDir, 'version.json');
  if (!existsSync(versionPath)) {
    logger.debug('No dist/version.json found, skipping release notification');
    return null;
  }

  try {
    const content = readFileSync(versionPath, 'utf-8');
    return JSON.parse(content) as VersionInfo;
  } catch (error) {
    logger.warn('Failed to read version.json', { error: (error as Error).message });
    return null;
  }
}

function stripWrappingQuotes(value: string): string {
  if (
    value.length >= 2 &&
    ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'")))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

function readRawEnvValue(key: string): string | undefined {
  if (!existsSync(ENV_FILE)) return undefined;

  try {
    const content = readFileSync(ENV_FILE, 'utf-8');
    for (const rawLine of content.split(/\r?\n/)) {
      const line = rawLine.trim();
      if (!line.startsWith(`${key}=`)) continue;

      const value = stripWrappingQuotes(line.slice(key.length + 1).trim());
      return value || undefined;
    }
  } catch (error) {
    logger.warn('Failed to read env file for notification channel fallback', {
      error: (error as Error).message,
      envFile: ENV_FILE,
      key,
    });
  }

  return undefined;
}

export function getConfiguredUpdateChannel(): string | undefined {
  const configured = process.env.DEFAULT_UPDATE_CHANNEL?.trim();
  if (configured) return configured;

  const recovered = readRawEnvValue('DEFAULT_UPDATE_CHANNEL')?.trim();
  if (recovered) {
    logger.info('Recovered DEFAULT_UPDATE_CHANNEL from raw env file', { envFile: ENV_FILE });
  }

  return recovered || undefined;
}

export function resolveChannel(client: WebClient, channelName: string): Promise<string | null> {
  // If it's already an ID (starts with C), return as-is
  if (channelName.startsWith('C')) return Promise.resolve(channelName);

  // Strip # prefix
  const name = channelName.replace(/^#/, '');

  return client.conversations
    .list({
      types: 'public_channel',
      limit: 1000,
    })
    .then((result) => {
      const channel = result.channels?.find((ch) => ch.name === name);
      return channel?.id || null;
    })
    .catch((error) => {
      const message = (error as Error).message;
      logger.warn('Failed to resolve channel name', { channelName, error: message });
      if (message.includes('missing_scope')) {
        logger.info('Falling back to direct channel name for notification delivery', { channelName });
        return channelName;
      }
      return null;
    });
}

export function formatTimestamp(isoTime: string): string {
  try {
    const date = new Date(isoTime);
    return `<!date^${Math.floor(date.getTime() / 1000)}^{date_short_pretty} {time}|${isoTime}>`;
  } catch {
    return isoTime;
  }
}

/**
 * Send release notification to the configured channel.
 * Call after app.start() succeeds.
 */
export async function notifyRelease(client: WebClient, paths: ReleaseNotifierPaths = defaultPaths()): Promise<void> {
  const channelConfig = getConfiguredUpdateChannel();
  if (!channelConfig) {
    logger.debug('DEFAULT_UPDATE_CHANNEL not set, skipping release notification');
    return;
  }

  const versionInfo = loadVersionInfo(paths.distDir);
  if (!versionInfo) return;

  // Once per deploy: a restart of the build this host already announced posts nothing.
  let notified: NotifiedRecord | undefined;
  try {
    notified = readJsonWithBackup(paths.notifiedFile, parseNotified);
  } catch (error) {
    logger.warn('release-notified record unusable; announcing this build', { error: (error as Error).message });
  }
  if (
    notified &&
    notified.tag === versionInfo.tag &&
    notified.commitHash === versionInfo.commitHash &&
    notified.buildTime === versionInfo.buildTime
  ) {
    logger.info('Release already announced on this host (restart); skipping', { version: versionInfo.version });
    return;
  }

  const previous = readOptionalJson<VersionInfo>(path.join(paths.distDir, 'previous-version.json'), 'previous-version');
  const history = readOptionalJson<ReleaseHistory>(path.join(paths.distDir, 'release-history.json'), 'release-history');
  const release = hostReleaseNotes(versionInfo, previous, history);

  const channelId = await resolveChannel(client, channelConfig);
  if (!channelId) {
    logger.warn('Could not resolve DEFAULT_UPDATE_CHANNEL', { channelConfig });
    return;
  }

  const isUpgrade = release.fromVersion !== '0.0.0' && versionInfo.version !== release.fromVersion;
  const isRollback = versionInfo.isRollback === true;

  const headerText = isRollback
    ? `⏪ *v${versionInfo.version}* 롤백 완료  _(v${release.fromVersion} → ${versionInfo.rollbackTargetTag || 'previous'})_`
    : isUpgrade
      ? `🚀 *v${versionInfo.version}* 배포 완료  _(v${release.fromVersion} → v${versionInfo.version})_`
      : `🚀 *v${versionInfo.version}* 배포 완료`;

  const blocks: any[] = [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: isRollback ? `⏪ soma-work v${versionInfo.version} 롤백` : `🚀 soma-work v${versionInfo.version} 배포`,
        emoji: true,
      },
    },
    {
      type: 'section',
      fields: [
        {
          type: 'mrkdwn',
          text: `*버전*\n\`${versionInfo.tag}\``,
        },
        {
          type: 'mrkdwn',
          text: `*브랜치*\n\`${versionInfo.branch}\``,
        },
        {
          type: 'mrkdwn',
          text: `*커밋*\n\`${versionInfo.commitHashShort}\``,
        },
        {
          type: 'mrkdwn',
          text: `*커밋 시간*\n${formatTimestamp(versionInfo.commitTime)}`,
        },
      ],
    },
  ];

  // Release notes section
  if (release.notes) {
    blocks.push(
      { type: 'divider' },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          // A section's text stops at 3000 characters (docs/misc/reference/slack-block-kit.md).
          text: `*📋 변경 사항*${isUpgrade ? ` _(${release.fromTag} → ${versionInfo.tag})_` : ''}\n\n${release.notes}`.slice(
            0,
            3000,
          ),
        },
      },
    );
  }

  // Footer
  blocks.push({
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `빌드: ${formatTimestamp(versionInfo.buildTime)} | 커밋: \`${versionInfo.commitHash.substring(0, 12)}\``,
      },
    ],
  });

  try {
    await client.chat.postMessage({
      channel: channelId,
      text: headerText,
      blocks,
      unfurl_links: false,
      unfurl_media: false,
    });
    logger.info('Release notification sent', {
      channel: channelConfig,
      version: versionInfo.version,
      from: release.fromTag,
      hostRelative: release.hostRelative,
    });
    try {
      atomicWriteJson(paths.notifiedFile, {
        tag: versionInfo.tag,
        commitHash: versionInfo.commitHash,
        buildTime: versionInfo.buildTime,
      } satisfies NotifiedRecord);
    } catch (error) {
      logger.warn('Failed to record the announced release; a restart will announce it again', {
        error: (error as Error).message,
      });
    }
  } catch (error) {
    logger.warn('Failed to send release notification', {
      error: (error as Error).message,
      channel: channelConfig,
    });
  }
}

/**
 * Get the current version info (for status display or other uses).
 */
export function getVersionInfo(): VersionInfo | null {
  return loadVersionInfo();
}
